      spend_amount
    }
  }
];

const earn_amount = items.length > 0
  ? items.reduce((sum, item) => {
      return sum + Number(item.json.amount || 0);
    }, 0)
  : 0;

return [
  {
    json: {
      earn_amount
    }
  }
];

// ===== 1. 取得基本資料 =====

const type = $('decider respond').first().json.type;
const replyToken = $('wash_data').first().json.replyToken;

let spend = 0;
let earn = 0;

// ===== 2. 根據查詢路徑讀取金額 =====

if (type === "spend") {

  // 單獨查詢支出
  spend = Number(
    $('spend_amount').first().json.spend_amount ?? 0
  );

} else if (type === "earn") {

  // 單獨查詢收入
  earn = Number(
    $('earn_amount').first().json.earn_amount ?? 0
  );

} else if (type === "both") {

  // 同時查詢支出與收入
  spend = Number(
    $('spend_amount1').first().json.spend_amount ?? 0
  );

  earn = Number(
    $('earn_amount1').first().json.earn_amount ?? 0
  );

} else {

  throw new Error(`Unknown query type: ${type}`);

}

if (!Number.isFinite(spend) || !Number.isFinite(earn)) {
  throw new Error("Invalid amount");
}

if (!replyToken) {
  throw new Error("Missing LINE replyToken");
}

if (!Number.isFinite(spend) || !Number.isFinite(earn)) {
  throw new Error("Invalid amount");
}


// ===== 2. Flex Bubble 產生函式 =====

function createBubble(kind, amount) {

  const isSpend = kind === "spend";

  const colors = isSpend
    ? {
        bg: "#F3EFF5",
        title: "#806A8F",
        line: "#C2B3C9",
        label: "#8F8295",
        amount: "#72547F"
      }
    : {
        bg: "#F8EFF3",
        title: "#B86F8A",
        line: "#D9B8C5",
        label: "#A98291",
        amount: "#A95778"
      };

  const texts = isSpend
    ? {
        title: "召喚支出",
        label: "總共花費",
        footer: "你理財，財理你 💰"
      }
    : {
        title: "召喚收入",
        label: "總共賺到",
        footer: "多多益善 💰"
      };

  const makeText = (text, size, color, extra = {}) => ({
    type: "text",
    text,
    size,
    color,
    align: "start",
    ...extra
  });

  return {
    type: "bubble",
    size: "micro",
    styles: {
      body: {
        backgroundColor: colors.bg
      }
    },
    body: {
      type: "box",
      layout: "vertical",
      paddingTop: "18px",
      paddingBottom: "18px",
      paddingStart: "20px",
      paddingEnd: "0px",
      contents: [
        makeText(texts.title, "lg", colors.title, {
          weight: "bold"
        }),

        makeText(
          "· · · · · · · · · · · ·",
          "xs",
          colors.line,
          { margin: "12px" }
        ),

        makeText(texts.label, "sm", colors.label),

        makeText(
          `NT$ ${amount.toLocaleString("en-US")}`,
          "xl",
          colors.amount,
          {
            weight: "bold",
            margin: "2px"
          }
        ),

        makeText(
          "· · · · · · · · · · · ·",
          "xs",
          colors.line,
          { margin: "8px" }
        ),

        makeText(texts.footer, "sm", colors.title, {
          margin: "2px",
          wrap: true
        })
      ]
    }
  };
}


// ===== 3. 根據查詢類型產生卡片 =====

const bubbles = [];

if (type === "spend" || type === "both") {
  bubbles.push(createBubble("spend", spend));
}

if (type === "earn" || type === "both") {
  bubbles.push(createBubble("earn", earn));
}


// ===== 4. Bubble / Carousel =====

const contents = bubbles.length === 1
  ? bubbles[0]
  : {
      type: "carousel",
      contents: bubbles
    };


// ===== 5. LINE altText =====

let altText;

if (type === "spend") {
  altText = `支出 NT$ ${spend.toLocaleString("en-US")}`;
} else if (type === "earn") {
  altText = `收入 NT$ ${earn.toLocaleString("en-US")}`;
} else {
  altText = `收支查詢｜支出 NT$ ${spend.toLocaleString("en-US")}，收入 NT$ ${earn.toLocaleString("en-US")}`;
}


// ===== 6. 建立 LINE Reply API Payload =====

const payload = {
  replyToken: replyToken,
  messages: [
    {
      type: "flex",
      altText: altText,
      contents: contents
    }
  ]
};


// ===== 7. 輸出給 HTTP Request =====

return [
  {
    json: payload
  }
];

const spend_amount = items.length > 0
  ? items.reduce((sum, item) => {
      return sum + Number(item.json.amount || 0);
    }, 0)
  : 0;

return [
  {
    json: {
      spend_amount
    }
  }
];

const earn_amount = items.length > 0
  ? items.reduce((sum, item) => {
      return sum + Number(item.json.amount || 0);
    }, 0)
  : 0;

return [
  {
    json: {
      earn_amount
    }
  }
];

const items = $input.all();
const totalAmount = items.reduce(
  (total, item) => total + item?.json?.amount,
  0,
);
return [{ json: { totalAmount }, pairedItem: items.map((_, index) => index) }];

const items = $input.all();
const totalAmount = items.reduce(
  (total, item) => total + item?.json?.amount,
  0,
);
return [{ json: { totalAmount }, pairedItem: items.map((_, index) => index) }];

const items = $input.all();
const totalAmount = items.reduce(
  (total, item) => total + item?.json?.amount,
  0,
);
return [{ json: { totalAmount }, pairedItem: items.map((_, index) => index) }];

const spend = $('read_spend_storage')
  .all()
  .map(item => item.json)
  .filter(row => Object.keys(row).length > 0);

const earn = $('read_earn_storage')
  .all()
  .map(item => item.json)
  .filter(row => Object.keys(row).length > 0);

// 取得上個月份（台灣時間）
const month = $now
  .setZone('Asia/Taipei')
  .minus({ months: 1 })
  .toFormat('yyyy-MM');

// 整合收入與支出
return [
  {
    json: {
      month,
      transactions: {
        spend,
        earn
      }
    }
  }
];

const records = $input.all()
  .map(item => item.json)
  .filter(row =>
    row &&
    Number.isInteger(Number(row.row_number)) &&
    Number(row.row_number) > 1
  )
  .map(row => ({
    ...row,
    row_number: Number(row.row_number)
  }));

return [
  {
    json: {
      record_count: records.length,
      records
    }
  }
];

const records = $('Pack Earn Rows').first().json.records || [];

// 錯誤回傳函式
function reject(reason, question = "") {
  return [{
    json: {
      error: reason,
      question
    }
  }];
}

// 1. 取得 AI 回傳的 JSON
let decision;

try {
  const input = $input.first().json;

  // 支援 Gemini 與一般 AI 節點輸出
  const raw =
    input.content?.parts?.find(p => typeof p.text === "string")?.text ??
    input.output ??
    input.text ??
    input;

  if (typeof raw === "string") {
    const cleaned = raw
      .trim()
      .replace(/^```(?:json)?\s*/i, "")
      .replace(/\s*```$/, "")
      .trim();

    decision = JSON.parse(cleaned);
  } else {
    decision = raw;
  }

} catch (error) {
  return reject("invalid_json", "AI 回傳的 JSON 無法解析");
}

// 2. 確認 AI 找到唯一紀錄
if (decision.status !== "matched") {
  return reject(
    decision.status || "unknown",
    decision.question || "找不到可確定修改的紀錄。"
  );
}

// 3. 驗證 row_number
const rowNumber = Number(decision.row_number);

if (!Number.isInteger(rowNumber) || rowNumber <= 1) {
  return reject("invalid_row_number");
}

const matches = records.filter(
  row => Number(row.row_number) === rowNumber
);

if (matches.length !== 1) {
  return reject(
    "row_not_found",
    `找不到第 ${rowNumber} 列的原始資料`
  );
}

const original = matches[0];

// 4. 檢查修改內容
const changes = decision.changes;

if (
  !changes ||
  typeof changes !== "object" ||
  Array.isArray(changes) ||
  Object.keys(changes).length === 0
) {
  return reject("invalid_changes");
}

// 5. 合併修改，保留未更動的欄位
const updated = { ...original };

// 不允許 AI 更動的系統欄位
const protectedFields = new Set([
  "row_number",
  "id",
  "transaction_id",
  "type",
  "source",
  "created_at",
  "updated_at"
]);

for (const [field, value] of Object.entries(changes)) {

  if (protectedFields.has(field)) {
    return reject(`protected_field: ${field}`);
  }

  if (!Object.prototype.hasOwnProperty.call(original, field)) {
    return reject(`unknown_field: ${field}`);
  }

  if (value === null || value === undefined) {
    return reject(`invalid_value: ${field}`);
  }

  // 收入金額必須為正數
  if (field === "amount") {
    if (
      typeof value !== "number" ||
      !Number.isFinite(value) ||
      value <= 0
    ) {
      return reject("invalid_amount");
    }
  }

  // tags 轉成 Google Sheets 可儲存的字串
  if (field === "tags") {
    if (
      !Array.isArray(value) ||
      !value.every(tag => typeof tag === "string")
    ) {
      return reject("invalid_tags");
    }

    updated[field] = JSON.stringify(value);
    continue;
  }

  if (
    typeof value !== "string" &&
    typeof value !== "number" &&
    typeof value !== "boolean"
  ) {
    return reject(`invalid_value: ${field}`);
  }

  updated[field] = value;
}

// 6. 輸出完整更新資料
return [{
  json: {
    ...updated,
    row_number: rowNumber
  }
}];

//
// Build Earn Update Flex
// 在 Google Sheets Update Row 成功後執行
//

// 1. 取得修改後資料
const updated = $('Validate Earn Update').first().json;

// 2. 取得修改前資料
const records = $('Pack Earn Rows').first().json.records || [];

const original = records.find(
  row => Number(row.row_number) === Number(updated.row_number)
);

if (!original) {
  throw new Error("找不到原始收入紀錄，無法製作修改摘要");
}

if (updated.error) {
  throw new Error("收入修改未通過驗證");
}

// 3. 取得 LINE replyToken
const replyToken = $('wash_data').first().json.replyToken;

if (!replyToken) {
  throw new Error("找不到 LINE replyToken");
}

// 4. 欄位名稱轉換
const fieldNames = {
  amount: "收入金額",
  currency: "幣別",
  category: "收入分類",
  subcategory: "子分類",
  merchant: "收入來源",
  payment_method: "收款方式",
  purpose: "收入用途",
  need: "需要程度",
  tags: "標籤",
  date: "日期",
  Date: "日期",
  time: "時間",
  Time: "時間"
};

// 5. 格式化欄位值
function formatValue(key, value) {
  if (value === null || value === undefined || value === "") {
    return "未填寫";
  }

  if (key === "amount") {
    const amount = Number(value);
    const currency = updated.currency || original.currency;

    if (Number.isFinite(amount)) {
      const number = amount.toLocaleString("en-US");
      if (currency === "TWD") return `${number} 元`;
      return currency ? `${number} ${currency}` : number;
    }
  }

  if (Array.isArray(value)) {
    return value.join("、") || "未填寫";
  }

  if (key === "tags" && typeof value === "string") {
    try {
      const parsed = JSON.parse(value);
      if (Array.isArray(parsed)) {
        return parsed.join("、") || "未填寫";
      }
    } catch (e) {}
  }

  return String(value);
}

// 6. 比對修改前後的欄位
function isSame(a, b) {
  if (a === b) return true;

  // 避免 Google Sheets 字串數字造成誤判
  if (
    a !== null && b !== null &&
    a !== "" && b !== "" &&
    !Array.isArray(a) && !Array.isArray(b) &&
    !isNaN(Number(a)) && !isNaN(Number(b))
  ) {
    return Number(a) === Number(b);
  }

  return JSON.stringify(a) === JSON.stringify(b);
}

const ignoredFields = new Set([
  "row_number",
  "id",
  "transaction_id",
  "type",
  "source",
  "created_at",
  "updated_at"
]);

const changes = [];

for (const [key, newValue] of Object.entries(updated)) {
  if (ignoredFields.has(key)) continue;
  if (!Object.prototype.hasOwnProperty.call(original, key)) continue;

  const oldValue = original[key];

  if (!isSame(oldValue, newValue)) {
    changes.push({
      key,
      label: fieldNames[key] || key,
      before: formatValue(key, oldValue),
      after: formatValue(key, newValue)
    });
  }
}

if (changes.length === 0) {
  throw new Error("沒有偵測到任何實際修改的欄位");
}

// 7. 建立每個欄位的比較區塊
const changeBlocks = changes.map(change => ({
  type: "box",
  layout: "vertical",
  spacing: "sm",
  margin: "md",
  contents: [
    {
      type: "text",
      text: change.label,
      size: "xs",
      weight: "bold",
      color: "#8F7885"
    },
    {
      type: "box",
      layout: "horizontal",
      spacing: "sm",
      contents: [
        {
          type: "text",
          text: change.before,
          size: "sm",
          color: "#999099",
          flex: 1,
          wrap: true
        },
        {
          type: "text",
          text: "→",
          size: "sm",
          color: "#B8A5B0",
          align: "center",
          flex: 0
        },
        {
          type: "text",
          text: change.after,
          size: "md",
          weight: "bold",
          color: "#A64F78",
          align: "end",
          flex: 1,
          wrap: true
        }
      ]
    }
  ]
}));

// 8. 建立粉色 Flex Bubble
const bubble = {
  type: "bubble",
  size: "kilo",
  body: {
    type: "box",
    layout: "vertical",
    backgroundColor: "#FFF7FA",
    paddingAll: "20px",
    spacing: "md",
    contents: [
      {
        type: "text",
        text: "收入修改成功！🌸",
        size: "xl",
        weight: "bold",
        color: "#A64F78",
        wrap: true
      },
      {
        type: "text",
        text: "已經幫你把這筆收入更新好啦",
        size: "sm",
        color: "#897986",
        wrap: true
      },
      {
        type: "separator",
        margin: "md",
        color: "#EBD7E1"
      },
      {
        type: "box",
        layout: "vertical",
        spacing: "md",
        contents: changeBlocks
      },
      {
        type: "separator",
        margin: "md",
        color: "#EBD7E1"
      },
      {
        type: "box",
        layout: "horizontal",
        margin: "sm",
        contents: [
          {
            type: "text",
            text: `本次修改 ${changes.length} 個欄位`,
            size: "xs",
            color: "#988692",
            flex: 1
          },
          {
            type: "text",
            text: "已同步 ✓",
            size: "xs",
            weight: "bold",
            color: "#B95E88",
            align: "end",
            flex: 1
          }
        ]
      }
    ]
  }
};

// 9. 輸出 LINE Messaging API 所需格式
return [
  {
    json: {
      replyToken,
      messages: [
        {
          type: "flex",
          altText: `收入修改成功！本次更新 ${changes.length} 個欄位`,
          contents: bubble
        }
      ]
    }
  }
];

// Pack Spend Rows: one item containing all candidate expense records.
// n8n Mode: Run Once for All Items
const event = $('wash_data').first().json;
const requesterId = event.userID ?? event.userId ?? event.user_id ?? event.source?.userId ?? null;

const allRows = $input.all()
  .map(item => item.json)
  .filter(row => row && Number.isInteger(Number(row.row_number)) && Number(row.row_number) > 1)
  .map(row => ({ ...row, row_number: Number(row.row_number) }));

// Limit records to the webhook sender when wash_data exposes their user ID.
const records = requesterId
  ? allRows.filter(row => String(row.userID ?? '') === String(requesterId))
  : allRows;

return [{ json: { record_count: records.length, records } }];

// Validate Spend Update: decode Gemini, verify target row, merge patch.
// Mode: Run Once for All Items
const records = $('Pack Spend Rows').first().json.records || [];
const fail = (error, question = '') => [{ json: { error, question } }];

let decision;
try {
  const input = $input.first().json;
  const raw = input.content?.parts?.find(p => typeof p.text === 'string')?.text
    ?? input.output ?? input.text ?? input;
  decision = typeof raw === 'string'
    ? JSON.parse(raw.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim())
    : raw;
} catch (e) {
  return fail('invalid_json', '系統無法解析修改內容，請再試一次。');
}

if (!decision || decision.status !== 'matched') {
  return fail(decision?.status || 'unknown', decision?.question || '目前無法確認要修改哪筆支出。');
}

const rowNumber = Number(decision.row_number);
if (!Number.isInteger(rowNumber) || rowNumber < 2) return fail('invalid_row_number');
const matches = records.filter(row => Number(row.row_number) === rowNumber);
if (matches.length !== 1) return fail('row_not_found', '找不到對應的支出紀錄。');
const original = matches[0];

// Optional but important account ownership check when wash_data provides user ID.
const event = $('wash_data').first().json;
const userId = event.userID ?? event.userId ?? event.user_id ?? event.source?.userId ?? null;
if (userId && String(original.userID ?? '') !== String(userId)) {
  return fail('user_mismatch', '這筆支出不屬於目前使用者，無法修改。');
}

const changes = decision.changes;
if (!changes || typeof changes !== 'object' || Array.isArray(changes) || Object.keys(changes).length === 0) {
  return fail('invalid_changes', '沒有收到有效的修改內容。');
}

const allowed = new Set([
  'date', 'time', 'amount', 'currency', 'category', 'subcategory',
  'merchant', 'payment method', 'purpose', 'need', 'tags'
]);
const updated = { ...original };
for (const [key, value] of Object.entries(changes)) {
  if (!allowed.has(key) || !Object.prototype.hasOwnProperty.call(original,key)) {
    return fail(`invalid_field: ${key}`, '修改內容包含不支援的欄位。');
  }
  if (value === null || value === undefined) return fail(`null_value: ${key}`);

  if (key === 'amount') {
    if (typeof value !== 'number' || !Number.isFinite(value) || value <= 0) {
      return fail('invalid_amount', '支出金額必須是大於零的數字。');
    }
    updated[key] = value;
  } else if (key === 'date') {
    if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
      return fail('invalid_date', '日期必須使用 yyyy-MM-dd 格式。');
    }
    const stamp = Date.parse(value + 'T00:00:00Z');
    if (!Number.isFinite(stamp) || new Date(stamp).toISOString().slice(0,10) !== value) {
      return fail('invalid_date', '日期無效。');
    }
    updated.date = value;
    if (Object.prototype.hasOwnProperty.call(original, 'tag_yy-MM')) {
      updated['tag_yy-MM'] = value.slice(0,7); // sheet actually stores yyyy-MM
    }
  } else if (key === 'tags') {
    if (!Array.isArray(value) || !value.every(x => typeof x === 'string')) {
      return fail('invalid_tags', '標籤應為文字陣列。');
    }
    updated.tags = JSON.stringify(value);
  } else {
    if (typeof value !== 'string') return fail(`invalid_value: ${key}`);
    updated[key] = value;
  }
}

return [{ json: { ...updated, row_number: rowNumber } }];

// Build Spend Update Flex: only after Google Sheets Update Row succeeds.
const updated = $('Validate Spend Update').first().json;
const records = $('Pack Spend Rows').first().json.records || [];
const original = records.find(r => Number(r.row_number) === Number(updated.row_number));
if (!original || updated.error) throw new Error('找不到可確認的支出修改紀錄');
const replyToken = $('wash_data').first().json.replyToken;
if (!replyToken) throw new Error('找不到 LINE replyToken');

const labels = {
  amount:'支出金額', currency:'幣別', category:'支出分類', subcategory:'子分類',
  merchant:'商家', 'payment method':'付款方式', purpose:'支出用途',
  need:'需要程度', tags:'標籤', date:'日期', time:'時間'
};
const ignored = new Set(['row_number','id','transaction_id','userID','type','source','tag_yy-MM','created_at','updated_at']);
function show(k,v) {
  if (v === null || v === undefined || v === '') return '未填寫';
  if (k === 'amount') {
    const s = Number(v).toLocaleString('en-US');
    const currency = updated.currency || original.currency;
    return currency === 'TWD' ? `${s} 元` : currency ? `${s} ${currency}` : `${s} 元`;
  }
  if (k === 'tags') {
    if (Array.isArray(v)) return v.join('、') || '未填寫';
    if (typeof v === 'string') {
      try { const arr = JSON.parse(v); if (Array.isArray(arr)) return arr.join('、') || '未填寫'; } catch(e) {}
    }
  }
  return String(v);
}
function normalize(k,v) {
  if (k==='amount') return Number(v);
  if (k==='tags') {
    if (typeof v==='string') { try {return JSON.stringify(JSON.parse(v));} catch(e){} }
    return JSON.stringify(v);
  }
  return String(v ?? '');
}
const changes=[];
for (const [key, after] of Object.entries(updated)) {
  if (ignored.has(key) || !Object.prototype.hasOwnProperty.call(original,key)) continue;
  const before=original[key];
  if (normalize(key,before) !== normalize(key,after)) {
    changes.push({label: labels[key] || key, before:show(key,before), after:show(key,after)});
  }
}

// A valid update can be a no-op if the requested value was already in the sheet.
if (!changes.length) {
  return [{json:{replyToken,messages:[{type:'text',text:'這筆支出的資料已經是你指定的內容，不需要再修改囉。'}]}}];
}

// Flex Message has practical size constraints. Show the first six changed fields.
const display=changes.slice(0,6);
const blocks=display.map(c=>({
  type:'box',layout:'vertical',spacing:'sm',margin:'md',contents:[
    {type:'text',text:c.label,size:'xs',weight:'bold',color:'#8F8295'},
    {type:'box',layout:'horizontal',spacing:'sm',contents:[
      {type:'text',text:c.before,size:'sm',color:'#8F8295',flex:1,wrap:true},
      {type:'text',text:'→',size:'sm',color:'#B1A1BB',align:'center',flex:0},
      {type:'text',text:c.after,size:'md',weight:'bold',color:'#72547F',align:'end',flex:1,wrap:true}
    ]}
  ]
}));
const bubble={
  type:'bubble',size:'kilo',body:{
    type:'box',layout:'vertical',backgroundColor:'#F3EFF5',paddingAll:'20px',spacing:'md',contents:[
      {type:'text',text:'支出修改成功！✨',size:'xl',weight:'bold',color:'#806A8F',wrap:true},
      {type:'text',text:'這筆支出已經更新好啦',size:'sm',color:'#8F8295',wrap:true},
      {type:'separator',margin:'md',color:'#C2B3C9'},
      {type:'box',layout:'vertical',spacing:'md',contents:blocks},
      {type:'separator',margin:'md',color:'#C2B3C9'},
      {type:'box',layout:'horizontal',margin:'sm',contents:[
        {type:'text',text:`本次修改 ${changes.length} 個欄位`,size:'xs',color:'#8F8295',flex:1},
        {type:'text',text:'已同步 ✓',size:'xs',color:'#806A8F',weight:'bold',align:'end',flex:1}
      ]}
    ]
  }
};
return [{json:{replyToken,messages:[{type:'flex',altText:`支出修改成功！本次更新 ${changes.length} 個欄位`,contents:bubble}]}}];

// Reply safely on ambiguous, not_found, or invalid updates.
const result=$input.first().json;
const replyToken=$('wash_data').first().json.replyToken;
if (!replyToken) throw new Error('找不到 LINE replyToken');
const text=result.question || (
  result.error === 'row_not_found' ? '找不到對應的支出紀錄，請再描述一次。' :
  '目前還不能確認要修改哪一筆支出，請提供金額、商家或日期。'
);
return [{json:{replyToken,messages:[{type:'text',text:String(text).slice(0,1500)}]}}];

// Build Earn Update Error Reply
// 只有驗證失敗時，才會走到這個節點。
const result = $input.first().json;
const replyToken = $('wash_data').first().json.replyToken;

if (!replyToken) {
  throw new Error('找不到 LINE replyToken');
}

const fallback = {
  ambiguous: '今天有多筆收入符合描述，請補充金額、來源或時間，以確認要修改哪一筆。',
  not_found: '找不到對應的收入紀錄，請確認日期、金額或收入來源。',
  row_not_found: '找不到指定的收入紀錄，請重新確認要修改的那筆收入。',
  invalid_json: '目前無法辨識修改內容，請換個方式描述要修改的收入。',
  invalid_changes: '沒有找到可以安全修改的欄位，請說明要修改的內容。',
  invalid_row_number: '無法確認收入紀錄的位置，請提供更多資料。',
  invalid_amount: '收入金額需為大於零的數字，請重新提供金額。'
};

const detail = String(
  result.question ||
  fallback[result.error] ||
  '目前無法確認要修改哪一筆收入，請提供日期、金額或收入來源。'
).trim();

const message = `這筆收入還沒修改成功 🌸\n\n${detail}`.slice(0, 1500);

return [{
  json: {
    replyToken,
    messages: [{ type: 'text', text: message }]
  }
}];

/**
 * n8n Code Node: Build Coffee Flex
 * Mode: Run Once for All Items
 *
 * Required nodes:
 * - Config
 * - readMonthSpend
 * - readTrivia
 *
 * Features:
 * - Daily spending summary
 * - Category breakdown
 * - Daily trivia rotation
 * - Single LINE Flex Bubble
 * - Asia/Taipei timezone
 *
 * Read-only: Does not modify Google Sheets or usage_log.
 */

// ========================================
// 1. 讀取資料
// ========================================

const config = $('Config').first().json;

const reportDate = String(config.reportDate || '').trim();

const spendRows = $('readMonthSpend')
  .all()
  .map(item => item.json);

const triviaRows = $input.all()
  .map(item => item.json);

const TZ = 'Asia/Taipei';


// ========================================
// 2. 日期處理
// ========================================

function validDate(y, m, d) {
  const date = new Date(
    Date.UTC(Number(y), Number(m) - 1, Number(d))
  );

  if (
    date.getUTCFullYear() !== Number(y) ||
    date.getUTCMonth() !== Number(m) - 1 ||
    date.getUTCDate() !== Number(d)
  ) {
    return null;
  }

  return `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
}

function taipeiDate(date) {
  if (!Number.isFinite(date.getTime())) return null;

  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: TZ,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(date);

  const part = type =>
    parts.find(p => p.type === type).value;

  return `${part('year')}-${part('month')}-${part('day')}`;
}

function dateKey(value) {
  if (
    typeof value === 'number' &&
    Number.isFinite(value) &&
    value > 0 &&
    value < 100000
  ) {
    return new Date(
      Date.UTC(1899, 11, 30) +
      Math.floor(value) * 86400000
    ).toISOString().slice(0, 10);
  }

  const raw = String(value ?? '').trim();

  if (
    /^\d{4}-\d{2}-\d{2}T.*(?:Z|[+-]\d{2}:?\d{2})$/i.test(raw)
  ) {
    return taipeiDate(new Date(raw));
  }

  const match = raw.match(
    /^(\d{4})[-/](\d{1,2})[-/](\d{1,2})(?:[ T]\d{1,2}:\d{2}(?::\d{2}(?:\.\d+)?)?)?$/
  );

  return match
    ? validDate(match[1], match[2], match[3])
    : null;
}

if (
  !/^\d{4}-\d{2}-\d{2}$/.test(reportDate) ||
  dateKey(reportDate) !== reportDate
) {
  throw new Error(
    'Config.reportDate 必須是台北日期 YYYY-MM-DD。'
  );
}

const displayDate = reportDate.replace(/-/g, '.');


// ========================================
// 3. 金額處理
// ========================================

function amountCents(value, row) {
  let raw = String(value ?? '')
    .trim()
    .replace(
      /(?:NT\$|TWD|NTD|＄|\$|元|,|\s)/gi,
      ''
    );

  if (/^\(.*\)$/.test(raw)) {
    raw = '-' + raw.slice(1, -1);
  }

  if (
    !/^[+-]?(?:\d+(?:\.\d{1,2})?|\.\d{1,2})$/.test(raw)
  ) {
    throw new Error(
      `spend_data 第 ${row} 列的 amount 無法辨識。`
    );
  }

  const cents = Math.round(
    Math.abs(Number(raw)) * 100
  );

  if (!Number.isSafeInteger(cents)) {
    throw new Error(
      `spend_data 第 ${row} 列金額超過計算範圍。`
    );
  }

  return cents;
}

const money = cents =>
  `NT$ ${(cents / 100).toLocaleString('en-US', {
    maximumFractionDigits: 2
  })}`;


// ========================================
// 4. 計算今日支出
// ========================================

const categoryCents = new Map();

let totalCents = 0;
let count = 0;

for (const [index, row] of spendRows.entries()) {

  // 跳過 Google Sheets 的空白輸出
  if (
    Object.entries(row).every(
      ([key, value]) =>
        key === 'row_number' ||
        value === '' ||
        value === null ||
        value === undefined
    )
  ) {
    continue;
  }

  const rowNumber = row.row_number || index + 2;

  const date = dateKey(row.date);

  if (!date) {
    throw new Error(
      `spend_data 第 ${rowNumber} 列缺少有效 date。`
    );
  }

  if (date !== reportDate) continue;

  const cents = amountCents(
    row.amount,
    rowNumber
  );

  const category =
    String(row.category ?? '').trim() || '其他';

  categoryCents.set(
    category,
    (categoryCents.get(category) || 0) + cents
  );

  totalCents += cents;

  if (!Number.isSafeInteger(totalCents)) {
    throw new Error('今日支出合計超過計算範圍。');
  }

  count++;
}

// 按照支出金額由大到小排序
const categories = [...categoryCents.entries()]
  .sort(
    (a, b) =>
      b[1] - a[1] ||
      a[0].localeCompare(b[0], 'zh-Hant')
  );


// ========================================
// 5. 選取每日冷知識
// ========================================

// 只選擇已發布的冷知識
const published = triviaRows
  .filter(
    row =>
      String(row.status ?? '')
        .trim()
        .toLowerCase() === 'published' &&
      String(row.fact ?? '').trim()
  )
  .sort(
    (a, b) =>
      String(a.id || a.fact)
        .localeCompare(String(b.id || b.fact))
  );

// 每日輪換一則
// 同一天重跑會選到相同內容
const dayIndex = Math.floor(
  Date.parse(reportDate + 'T00:00:00Z') /
  86400000
);

const selected = published.length
  ? published[dayIndex % published.length]
  : null;

const triviaText = selected
  ? String(selected.fact).trim()
  : '今天還沒有冷知識可以分享。';


// ========================================
// 6. Flex Message 色彩設定
// ========================================

const C = {
  header: '#9B7D6D',
  cream: '#FFF8F0',
  primary: '#59463D',
  secondary: '#75675E',
  muted: '#99877B',
  line: '#E5D8CD',
  quoteBg: '#F3EBE4',
  quoteText: '#69574D',
  dateLine: '#CBB9AD',
  white: '#FFFFFF'
};


// ========================================
// 7. Flex Message 元件工具
// ========================================

function text(value, options = {}) {
  const content = String(value);

  if (
    !content ||
    [...content].length > 2000
  ) {
    throw new Error(
      '卡片文字為空或超過 LINE 單一文字元件上限。'
    );
  }

  return {
    type: 'text',
    text: content,
    size: 'sm',
    color: C.primary,
    wrap: true,
    ...options
  };
}

function box(contents, options = {}) {
  return {
    type: 'box',
    layout: 'vertical',
    contents,
    ...options
  };
}

function separator(margin = 'xl') {
  return {
    type: 'separator',
    margin,
    color: C.line
  };
}


// ========================================
// 8. 製作標題區域
// ========================================

const header = box(
  [
    text('Daily Summary', {
      size: 'xxl',
      weight: 'bold',
      align: 'center',
      color: C.white
    })
  ],
  {
    backgroundColor: C.header,
    paddingAll: '16px'
  }
);


// ========================================
// 9. 製作分類支出明細
// ========================================

// 分類靠左
// 金額靠左
// flex 比例為 1:3

const rows = categories.map(([name, cents]) =>
  box(
    [
      text(name, {
        size: 'sm',
        color: C.secondary,
        flex: 1
      }),

      text(money(cents), {
        size: 'sm',
        weight: 'bold',
        color: C.primary,
        align: 'start',
        flex: 3
      })
    ],
    {
      layout: 'horizontal',
      spacing: 'none'
    }
  )
);

// 如果今天沒有支出
const spendingDetails = rows.length
  ? rows
  : [
      text('今天尚無支出紀錄。', {
        color: C.muted,
        size: 'sm'
      })
    ];


// ========================================
// 10. 製作冷知識方框
// ========================================

// 僅顯示一句冷知識
// 不顯示分類、來源或按鈕

const triviaBox = box(
  [
    text(`“${triviaText}”`, {
      size: 'sm',
      color: C.quoteText,
      align: 'center',
      wrap: true
    })
  ],
  {
    backgroundColor: C.quoteBg,
    cornerRadius: '10px',
    paddingAll: '14px',
    margin: 'xl'
  }
);


// ========================================
// 11. 製作底部日期
// ========================================

// 日期置中，兩側顯示橫線

const dateBox = box(
  [
    text('────────', {
      size: 'xs',
      color: C.dateLine,
      align: 'end',
      flex: 1,
      wrap: false
    }),

    text(displayDate, {
      size: 'xs',
      color: C.muted,
      align: 'center',
      flex: 2,
      wrap: false
    }),

    text('────────', {
      size: 'xs',
      color: C.dateLine,
      align: 'start',
      flex: 1,
      wrap: false
    })
  ],
  {
    layout: 'horizontal',
    spacing: 'sm',
    margin: 'lg'
  }
);


// ========================================
// 12. 合併成最終 Flex Bubble
// ========================================

const spendBubble = {
  type: 'bubble',
  size: 'kilo',

  header,

  body: box(
    [
      // 今日總金額（靠左）
      text(money(totalCents), {
        size: 'xxl',
        weight: 'bold',
        color: C.primary,
        align: 'start',
        margin: 'md'
      }),

      // 分隔線
      separator('xl'),

      // 各類別支出
      box(spendingDetails, {
        spacing: 'lg',
        margin: 'xl'
      }),

      // 支出筆數（靠右）
      text(`共 ${count} 筆支出`, {
        size: 'xs',
        color: C.muted,
        align: 'end',
        margin: 'lg'
      }),

      // 分隔線
      separator('xl'),

      // 今日冷知識
      triviaBox,

      // 底部日期
      dateBox
    ],
    {
      backgroundColor: C.cream,
      paddingAll: '22px'
    }
  )
};


// ========================================
// 13. 檢查 Flex Message 大小
// ========================================

function utf8Bytes(value) {
  return [...value].reduce((sum, char) => {
    const c = char.codePointAt(0);

    return sum + (
      c <= 0x7f
        ? 1
        : c <= 0x7ff
          ? 2
          : c <= 0xffff
            ? 3
            : 4
    );
  }, 0);
}

if (
  utf8Bytes(JSON.stringify(spendBubble)) > 29000
) {
  throw new Error(
    'Flex Bubble 內容接近 LINE 30 KB 上限。'
  );
}


// ========================================
// 14. 建立 LINE Push Message
// ========================================

// 最終只輸出一則 Flex Message

const messages = [
  {
    type: 'flex',

    altText:
      `${reportDate} 今日支出 ${money(totalCents)}，共 ${count} 筆`,

    contents: spendBubble
  }
];


// ========================================
// 15. 輸出給 HTTP Request
// ========================================

// 保留原本的 to、messages 格式
// 可直接接 Send LINE Flex 節點

return [
  {
    json: {
      to: String(config.lineTo || '').trim(),

      messages,

      reportDate,

      today: {
        total: totalCents / 100,
        count,
        categories: Object.fromEntries(
          categories.map(([name, cents]) => [
            name,
            cents / 100
          ])
        )
      },

      triviaId: selected
        ? String(selected.id || '')
        : null,

      setupRequired:
        !/^[UCR][0-9a-f]{32}$/i.test(
          String(config.lineTo || '').trim()
        )
    }
  }
];
